func marshalDisplayviewsParticipantViewToParticipantResponseBody(v *displayviews.ParticipantView) *ParticipantResponseBody {
	if v == nil {
		return nil
	}
	res := &ParticipantResponseBody{
		ID:        *v.ID,
		Role:      *v.Role,
		Connected: *v.Connected,
		JoinedAt:  *v.JoinedAt,
	}

	return res
}

// marshalDisplayviewsDisplayCapabilityViewToDisplayCapabilityResponseBody
// builds a value of type *DisplayCapabilityResponseBody from a value of type
// *displayviews.DisplayCapabilityView.
func marshalDisplayviewsDisplayCapabilityViewToDisplayCapabilityResponseBody(v *displayviews.DisplayCapabilityView) *DisplayCapabilityResponseBody {
	if v == nil {
		return nil
	}
	res := &DisplayCapabilityResponseBody{
		Enabled:            *v.Enabled,
		Protocol:           *v.Protocol,
		MaxParticipants:    v.MaxParticipants,
		MaxWidth:           v.MaxWidth,
		MaxHeight:          v.MaxHeight,
		HandshakeTimeoutMs: v.HandshakeTimeoutMs,
		ParticipantTTLMs:   v.ParticipantTTLMs,
		Participants:       v.Participants,
		ControllerPresent:  v.ControllerPresent,
	}
	if v.Transports != nil {
		res.Transports = make([]string, len(v.Transports))
		for i, val := range v.Transports {
			res.Transports[i] = val
		}
	}

	return res
}
